import json,html
def page(rows,path,title,nav='',prefix=''):
 items=[{'id':x['sample_id'],'smiles':x.get('SMILES',''),'view':prefix+x.get('band_line_view_check',x['view_check']),'ann':prefix+x['annotation']} for x in rows]
 text='''<!doctype html><meta charset="utf-8"><title>TITLE</title><style>body{font:16px sans-serif;margin:24px;background:#eee}article{background:#fff;padding:12px;margin:12px 0}img{max-width:100%}input,button{font:inherit;margin:6px;padding:6px}</style><h1>TITLE</h1>NAV<p>并排查看 band、line 及原子／电荷框；坐标均属于生成图。</p><input id="q" placeholder="本页 sample ID / SMILES"><button id="prev">上 16 张</button><button id="next">下 16 张</button><span id="count"></span><main id="list"></main><script>const data=DATA,q=document.getElementById('q'),list=document.getElementById('list'),count=document.getElementById('count'),prev=document.getElementById('prev'),next=document.getElementById('next');let p=0;function render(){let r=data.filter(x=>x.id.includes(q.value)||x.smiles.includes(q.value));p=Math.max(0,Math.min(p,Math.ceil(r.length/16)-1));list.replaceChildren();for(let x of r.slice(p*16,p*16+16)){let a=document.createElement('article'),t=document.createElement('p');t.textContent=x.id+' | '+x.smiles;a.append(t);let l=document.createElement('a');l.href=x.ann;l.textContent='annotation JSON';a.append(l);let im=document.createElement('img');im.src=x.view;im.loading='lazy';a.append(im);list.append(a)}count.textContent=r.length+' images; '+(p+1)}q.oninput=()=>{p=0;render()};prev.onclick=()=>{p--;render()};next.onclick=()=>{p++;render()};render()</script>'''
 text=text.replace('TITLE',html.escape(title)).replace('NAV',nav).replace('DATA',json.dumps(items,ensure_ascii=True).replace('<','\\u003c'));path.write_text(text)

